    suspend fun getRandomWord(category: String? = null, difficulty: String? = null, includeBadWords: Boolean = false): WordEntity {
        val allWords = when {
            category != null && category != "All" && difficulty != null && difficulty != "Mixed" -> 
                wordDao.getWordsByCategoryAndDifficulty(category, difficulty)
            category != null && category != "All" -> 
                wordDao.getWordsByCategory(category)
            difficulty != null && difficulty != "Mixed" -> 
                wordDao.getWordsByDifficulty(difficulty)
            else -> wordDao.getAllActiveWords()
        }

        val filteredWords = allWords.filter { word ->
            if (!includeBadWords && word.category == "PROFANITY_INSULT") {
                false
            } else {
                true
            }
        }

